SCHEMA_RAFFLES = "CREATE TABLE IF NOT EXISTS raffles (\n id INTEGER PRIMARY KEY,\n title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 150),\n description TEXT NOT NULL DEFAULT '',\n prizes TEXT NOT NULL DEFAULT '',\n number_start INTEGER NOT NULL CHECK(number_start>=0),\n number_end INTEGER NOT NULL CHECK(number_end>=number_start),\n number_width INTEGER NOT NULL CHECK(number_width BETWEEN 1 AND 12),\n donation_cents INTEGER NOT NULL CHECK(donation_cents>=0),\n draw_at TEXT,\n status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed','finished')),\n created_by TEXT NOT NULL,\n created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n image_filename TEXT,\n extended_info TEXT\n);"
